-- =============================================================================-- File:    20261110130000_silver_065_alert_outbox.sql-- Gap:     4 (fallbacks-design.md) GÇö Alert delivery: outbox + edge function-- Status:  IMPLEMENTS GAP 4. pg_net + sidnl-alerts cron are OPTIONAL enable--          steps at the bottom (run only after the alert-dispatch edge--          function is deployed and its secrets set).-- Decisions: Q5 = pg_net + Slack; delivery disabled-by-default via config;--            at-most-once on crash (reclaimed 'sending' rows -> failed).-- Rollback: 062_rollback.sql-- Principle: additive only; existing cron/storage alert writers unchanged.-- =============================================================================-- ----------------------------------------------------------------------------- 1. Config (disabled by default GÇö flip to 1 after edge function is live)-- ---------------------------------------------------------------------------insert into silver.sidnl_config(key, value_num, description) values  ('alert_delivery_enabled', 0, '1 = edge function may deliver outbox rows; 0 = collect only'),  ('alert_max_attempts',     6, 'delivery attempts before an alert is marked dead'),  ('alert_claim_timeout_minutes', 5, 'rows stuck in sending longer than this are reclaimed (marked failed, at-most-once)')on conflict (key) do nothing;-- ----------------------------------------------------------------------------- 2. Outbox table (state only; safe to drop/recreate)-- ---------------------------------------------------------------------------create table if not exists ops.alert_outbox(  alert_id        bigint generated always as identity primary key,  dedupe_key      text unique not null,  source          text not null check (source in                    ('cron','storage','freshness','gold','dead_letter','heartbeat')),  severity        text not null default 'warning' check (severity in ('info','warning','critical')),  title           text not null,  body            text,  created_at      timestamptz not null default now(),  status          text not null default 'pending' check (status in                    ('pending','sending','sent','failed','dead','disabled')),  attempts        int  not null default 0,  next_attempt_at timestamptz not null default now(),  claimed_at      timestamptz,  sent_at         timestamptz,  last_error      text,  channel         text not null default 'slack');-- match existing ops tables: RLS on, no policies (service role reads/writes)alter table ops.alert_outbox enable row level security;create index if not exists alert_outbox_pending_idx  on ops.alert_outbox (next_attempt_at) where status = 'pending';-- ----------------------------------------------------------------------------- 3. Triggers: existing alert writers feed the outbox (deduped)-- ---------------------------------------------------------------------------create or replace function ops.alert_log_to_outbox() returns triggerlanguage plpgsql as $$begin  insert into ops.alert_outbox(dedupe_key, source, severity, title, body)  values (    tg_argv[0] || ':' || coalesce(new.alert_id::text, gen_random_uuid()::text),    tg_argv[0],    coalesce(new.severity::text, 'warning'),    coalesce(new.title::text, tg_argv[0] || ' alert'),    coalesce(new.details::text, new.message::text, '')  )  on conflict (dedupe_key) do nothing;  return new;end $$;drop trigger if exists trg_cron_alert_outbox on ops.cron_alert_log;create trigger trg_cron_alert_outbox  after insert on ops.cron_alert_log  for each row execute function ops.alert_log_to_outbox('cron');drop trigger if exists trg_storage_alert_outbox on ops.storage_alert_log;create trigger trg_storage_alert_outbox  after insert on ops.storage_alert_log  for each row execute function ops.alert_log_to_outbox('storage');-- ----------------------------------------------------------------------------- 4. Claim / mark API (used by the edge function)-- ---------------------------------------------------------------------------create or replace function ops.alert_claim(p_limit int default 10)returns table(alert_id bigint, source text, severity text, title text, body text, attempts int)language plpgsql security definer as $$begin  -- delivery off: keep collecting, deliver nothing  if coalesce(silver.cfg('alert_delivery_enabled'), 0) <> 1 then    return;  end if;  -- at-most-once: reclaim stale 'sending' rows as failed (never resend)  update ops.alert_outbox     set status = 'failed',         last_error = 'reclaimed: stuck in sending past claim timeout'   where status = 'sending'     and claimed_at < now() - make_interval(mins => silver.cfg('alert_claim_timeout_minutes'));  return query  update ops.alert_outbox o     set status = 'sending', claimed_at = now(), attempts = o.attempts + 1   where o.alert_id in (     select a.alert_id from ops.alert_outbox a      where a.status = 'pending' and a.next_attempt_at <= now()      order by a.alert_id      for update skip locked      limit p_limit   )   returning o.alert_id, o.source, o.severity, o.title, o.body, o.attempts;end $$;create or replace function ops.alert_mark(p_alert_id bigint, p_ok bool, p_err text default null)returns void language plpgsql security definer as $$begin  if p_ok then    update ops.alert_outbox       set status='sent', sent_at=now(), last_error=null     where alert_id = p_alert_id;  else    update ops.alert_outbox o       set status = case              when o.attempts >= silver.cfg('alert_max_attempts') then 'dead'              else 'pending' end,           next_attempt_at = now() + make_interval(mins => silver.backoff_minutes(o.attempts)),           last_error = p_err     where o.alert_id = p_alert_id;  end if;end $$;-- ----------------------------------------------------------------------------- 5. Health view-- ---------------------------------------------------------------------------create or replace view ops.v_alert_outbox_healthwith (security_invoker = true) asselect  count(*) filter (where status='pending')                    as pending,  count(*) filter (where status='dead')                       as dead,  count(*) filter (where status='failed')                     as failed,  max(now() - created_at)      filter (where status='pending')                         as oldest_pending_agefrom ops.alert_outbox;-- ----------------------------------------------------------------------------- 6. OPTIONAL ENABLE STEPS (run manually after deploying edge function):----    a) create edge function 'alert-dispatch' (code: data-sidnl/edge-functions/alert-dispatch/index.ts)--       and set its secret:  supabase secrets set SLACK_WEBHOOK_URL=...   (set it YOURSELF; never paste here)--    b) enable pg_net:  create extension if not exists pg_net;--    c) poll cron (URL below is the project's functions host):--       select cron.schedule('sidnl-alerts', '* * * * *', $$--         set statement_timeout='30s';--         perform net.http_post(--           url     := 'https://jqxnaqbvwgmfkyzfincy.supabase.co/functions/v1/alert-dispatch',--           headers := jsonb_build_object('Authorization','Bearer ' || vault decryption of service key),--           body    := '{}'::jsonb);--       $$);--    d) flip the switch:  update silver.sidnl_config set value_num=1 where key='alert_delivery_enabled';----    The service key must be stored via supabase vault (vault.create_secret) and--    read inside the cron command GÇö never inlined here.-- ---------------------------------------------------------------------------